package com.hmdp.ai.infrastructure.dify;import com.fasterxml.jackson.databind.JsonNode;import com.hmdp.ai.domain.external.DifyWorkflowGateway;import org.springframework.stereotype.Component;@Component public class DifyToolExecutor {private final DifyWorkflowGateway gateway;public DifyToolExecutor(DifyWorkflowGateway gateway){this.gateway=gateway;}public JsonNode execute(JsonNode configuration,JsonNode input,String userId,String runId,int timeoutMs){return gateway.run(configuration,input,userId,runId,timeoutMs);}}
